DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "est2-papers-2026-09-26:l2june:q15", "old_status": "needs_source_repair", "status": "ready", "question_id": "0bd86cbf-8704-54be-8c51-08d98401913f", "stem": "Which piecewise formula agrees with the three line segments shown, away from the breakpoints x=−2 and x=3?", "choices": [{"key": "A", "text": "\\(f(x)=\\begin{cases}x-3&x<-2\\\\2x-1&-2\\le x<3\\\\-x/2-2&x\\ge3\\end{cases}\\)"}, {"key": "B", "text": "\\(f(x)=\\begin{cases}x+3&x<-2\\\\2x-1&-2\\le x<3\\\\-x/2-2&x\\ge3\\end{cases}\\)"}, {"key": "C", "text": "\\(f(x)=\\begin{cases}x-3&x<-2\\\\2x+1&-2\\le x<3\\\\-x/2-2&x\\ge3\\end{cases}\\)"}, {"key": "D", "text": "\\(f(x)=\\begin{cases}-x+3&x<-2\\\\2x-1&-2\\le x<3\\\\x/2-2&x\\ge3\\end{cases}\\)"}, {"key": "E", "text": "\\(f(x)=\\begin{cases}x+3&x<-2\\\\2x-1&-2\\le x<3\\\\-x/2+2&x\\ge3\\end{cases}\\)"}], "type": "mcq", "correct": "E", "explanation": "The left segment has slope 1 and passes through (−3,0), giving y=x+3. The middle segment has slope 2 and y-intercept −1, giving y=2x−1. The right segment has slope −1/2 and passes through (4,0), giving y=−x/2+2. Only E has all three expressions. The source does not mark endpoint inclusion clearly, so the prompt deliberately asks about the segments away from the breakpoints.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Restored the source graph and scoped the question to the three line formulas, which uniquely identify E without assuming missing endpoint markers.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 5, "assets": {"figure": "data:image/jpeg;base64,"}}, {"id": "est2-papers-2026-09-26:l2june:q24", "old_status": "needs_source_repair", "status": "ready", "question_id": "6d879c43-fa32-59d5-8fd3-bf7d2620c678", "stem": "A sample of seven daily pizza sales counts is 42, 37, 26, 40, 42, 50, 41. What is half the sample standard deviation, rounded to two decimal places?", "choices": [{"key": "A", "text": "2.84"}, {"key": "B", "text": "3.61"}, {"key": "C", "text": "5.85"}, {"key": "D", "text": "7.22"}, {"key": "E", "text": "19.86"}], "type": "mcq", "correct": "B", "explanation": "The sample mean is 278/7≈39.714286. The sum of squared deviations is 2194/7≈313.428571. Divide by n−1=6 to get sample variance 1097/21≈52.238095. Half the square root is approximately 3.6138, which rounds to 3.61.", "topic": "Statistics, Probability & Data Analysis", "note": "Original source image decrypted, hash checked, and visually inspected. Specified sample standard deviation, the convention matching the source choices.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 7}, {"id": "est2-papers-2026-09-26:l2june:q32", "old_status": "needs_source_repair", "status": "ready", "question_id": "6ac3fdb6-0f06-5c8f-90ee-9c3e43f1cb6b", "stem": "Three odd integers, each greater than 1, have product 231. What is their sum?", "choices": [{"key": "A", "text": "9"}, {"key": "B", "text": "19"}, {"key": "C", "text": "21"}, {"key": "D", "text": "33"}, {"key": "E", "text": "77"}], "type": "mcq", "correct": "C", "explanation": "The prime factorization is 231=3×7×11. Because all three factors are integers greater than 1, each must contain at least one prime factor. There are exactly three prime factors, so the three integers must be 3, 7, and 11 in some order. Their sum is 21.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original source image decrypted, hash checked, and visually inspected. Added “each greater than 1” to exclude the original alternatives involving 1, such as 1×11×21.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 9}, {"id": "est2-papers-2026-09-26:l2june:q34", "old_status": "needs_source_repair", "status": "ready", "question_id": "77400e2a-a414-5b01-857d-0c94f2e7c901", "stem": "Which listed family consists entirely of exact solutions to \\(3\\sin x+2\\sin2x=0\\) for every integer n? Angles are in radians; the decimal numbers in the choices are exact as written.", "choices": [{"key": "A", "text": "x = 3.86 − πn"}, {"key": "B", "text": "x = −2πn"}, {"key": "C", "text": "x = 2.42 − πn"}, {"key": "D", "text": "x = 3.86 + πn"}, {"key": "E", "text": "x = 2.42 + 2πn"}], "type": "mcq", "correct": "B", "explanation": "Use sin 2x=2sin x cos x to factor the equation as sin x(3+4cos x)=0. Its full solution is x=kπ or x=±arccos(−3/4)+2kπ, where k is an integer. Every x=−2πn is an exact solution. The values 2.42 and 3.86 are rounded approximations, not exact values of arccos(−3/4) or its other branch, so the other listed families do not consist of exact solutions.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Explicitly distinguished exact solutions from rounded approximations, resolving the B/E precision ambiguity.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 9}, {"id": "est2-papers-2026-09-26:l2june:q39", "old_status": "needs_source_repair", "status": "ready", "question_id": "b927982b-5e81-56d8-a4e4-3de4ff419aab", "stem": "Triangle ABC has angle A=28°, AC=12 cm, and BC=7.5 cm. Which value could be its area, rounded to the nearest hundredth of a square centimeter?", "choices": [{"key": "A", "text": "15.90 cm²"}, {"key": "B", "text": "21.12 cm²"}, {"key": "C", "text": "44.22 cm²"}, {"key": "D", "text": "253.80 cm²"}, {"key": "E", "text": "930.15 cm²"}], "type": "mcq", "correct": "A", "explanation": "By the sine rule, sin B=12sin(28°)/7.5≈0.7511545. Thus B≈48.6905° or 131.3095°, and C≈103.3095° or 20.6905°. The area is (1/2)(12)(7.5)sin C. The two possibilities are approximately 43.7913 and 15.8994 cm², rounding to 43.79 and 15.90. Only 15.90 is listed.", "topic": "Triangles, Trigonometry & Similarity", "note": "Original source image decrypted, hash checked, and visually inspected. Transcribed all diagram data into the stem and corrected A from 15.89 to 15.90. The wording “could” correctly accommodates the two SSA triangles.", "source_document": "EST II - Math Level 2 - June 2021.pdf", "source_page": 10}, {"id": "est2-papers-2026-09-26:l2may:q22", "old_status": "needs_source_repair", "status": "ready", "question_id": "427b4627-3d6c-5b2a-8490-8a7cf1272b3e", "stem": "Which statement is true about \\(f(x)=\\frac{(x-1)(x+3)}{(x^2+1)(x^2-1)}\\)?", "choices": [{"key": "A", "text": "The graph has no horizontal asymptote."}, {"key": "B", "text": "The graph has two vertical asymptotes."}, {"key": "C", "text": "The graph touches the x-axis at x=3."}, {"key": "D", "text": "The graph lies below the x-axis when x<−3."}, {"key": "E", "text": "The graph has a hole at x=1."}], "type": "mcq", "correct": "E", "explanation": "Factor x²−1=(x−1)(x+1). For x≠±1, f(x)=(x+3)/[(x²+1)(x+1)]. Cancellation creates a hole at x=1, with limiting y-value 1. There is one vertical asymptote, x=−1; the horizontal asymptote is y=0; and the x-intercept is −3. For x<−3 both x+3 and x+1 are negative, so f(x)>0. Only E is true after correcting D.", "topic": "Functions, Transformations & Graphs", "note": "Original source image decrypted, hash checked, and visually inspected. Corrected D from “above” to “below”; the original D and E were both true. Original text is preserved in the audit backup.", "source_document": "EST II - Math Level 2 - May 2021.pdf", "source_page": 9}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='source_review_20260928' AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_20260928','source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
